class Solution:
    def maximumOr(self, nums: List[int], k: int) -> int:
        n = len(nums)
        pre = [0] * (n + 1)
        suf = [0] * (n + 1)
        for i in range(n): pre[i + 1] = pre[i] | nums[i]
        for i in range(n - 1, -1, -1): suf[i] = suf[i + 1] | nums[i]
        best = 0
        for i in range(n):
            rest = pre[i] | suf[i + 1]
            for t in range(k + 1):
                best = max(best, rest | (nums[i] << t))
        return best

