class Solution {
public:
    long long maximumOr(vector<int>& nums, int k) {
        int n = nums.size();
        vector<long long> pre(n + 1, 0), suf(n + 1, 0);
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] | nums[i];
        for (int i = n - 1; i >= 0; i--) suf[i] = suf[i + 1] | nums[i];
        long long best = 0;
        for (int i = 0; i < n; i++) {
            long long rest = pre[i] | suf[i + 1];
            for (int t = 0; t <= k; t++)
                best = max(best, rest | ((long long)nums[i] << t));
        }
        return best;
    }
};

