class Solution:
    def maximumOr(self, nums: List[int], k: int) -> int:
        from collections import Counter
        cnt = Counter()
        for x in nums:
            b = 0
            while x >> b:
                if (x >> b) & 1: cnt[b] += 1
                b += 1
        best = 0
        for x in nums:
            rest = 0
            for b in range(35):
                c = cnt[b] - ((x >> b) & 1)
                if c > 0: rest |= 1 << b
            for t in range(k + 1):
                best = max(best, rest | (x << t))
        return best

